contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint lockTime, uint deposit, uint minSum, uint collectAmount) public payable {
        require(deposit >= 1 ether);
        require(address(this).balance >= deposit);
        require(collectAmount <= deposit);
        require(collectAmount <= deposit);

        // Set up a fresh state: set the minimum sum and lock a positive deposit.
        c.SetMinSum(minSum);
        c.Put{value: deposit}(lockTime);

        // Make the state reachable for Collect: time must be past unlockTime.
        // Since unlockTime was set to block.timestamp + lockTime (or 0), we need to ensure it is in the past.
        // We cannot control block.timestamp, so choose lockTime = 0 to make unlockTime 0 (past).
        // However, lockTime is a parameter; we require it to be 0 to make unlockTime 0.
        // This is a valid restriction: general rule still holds for all inputs where it is applicable.
        require(lockTime == 0);

        // Read the before state.
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        // Perform Collect.
        bool collected;
        try c.Collect(collectAmount) {
            collected = true;
        } catch {
            collected = false;
        }

        // Read the after state.
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        assert(!collected || (afterBalance == beforeBalance - collectAmount && afterContractBalance == beforeContractBalance - collectAmount));
    }

    receive() external payable {}
}

